// Arena (map) data — pure JS. The shared sim only needs the obstacles,
// surfaces, and spawn positions for collision and respawn logic. Mesh
// creation stays client-side.

import { GROUND_BASE_Y } from './constants.js';

// Each obstacle is an axis-aligned bounding box (AABB) used for unit and
// projectile collision. Optional flags:
//   topBuffer    — units above maxY+topBuffer are NOT colliding (for jumping
//                  over short obstacles); default 4.
//   noProjectile — projectiles pass through (for unit-only fences).
//   blocksBotSight — bot LINE OF SIGHT treats this box as opaque even when
//                  noProjectile lets bullets through. For invisible movement
//                  bars (Streets' under-slope walls): a see-through wall the
//                  bot cannot walk through defeats every Maze trigger and
//                  the bot paces against it (2026-08-13).
//
// Surfaces describe walkable ground at non-zero heights (platforms, ramps).
// heightAt(x, z) returns the surface Y for a point inside the surface bbox.

// Per-map play-area half-extents. Wall obstacles are placed at ±halfX
// (along X) and ±halfZ (along Z) — same positions where the offline
// `addBoundaryIndicator` helper draws its red ground stripes inside
// client/src/main.js. Lobby and Station never had an indicator in offline
// either, so they fall back to the original ±138 outer cannon-wall extent.
// Any map id not listed here defaults to ±138 (matching the previous
// global behaviour).
const MAP_BOUNDARY = {
  arena1:     { halfX: 120, halfZ: 120 },  // Plain Field
  arena2:     { halfX: 136, halfZ:  92 },  // Streets (halfX +8: map extended for the doubled bridge, 2026-08-14)
  factory:    { halfX: 130, halfZ: 105 },
  factory2:   { halfX: 130, halfZ: 105 },
  square:     { halfX: 116, halfZ: 106 },
  lobby:      { halfX: 138, halfZ: 138 },
  station:    { halfX: 138, halfZ: 138 },
  flashpoint: { halfX: 110, halfZ:  75 },
  airport:    { halfX: 138, halfZ: 112 },
  town:       { halfX: 270, halfZ: 200 },   // Invasion Map, the town block (135 x 100 m at 4 units per metre)
  spacecraft: { halfX: 240, halfZ: 140, ceil: 5.2 },   // The Skeld (Among Us), the whole ship (118 x 69 m at 4 units per metre, 14 m per model unit)
  dust:       { halfX: 227.6, halfZ: 355.6 },   // Dust2-short, the middle of the map — the site, the pit, the yards (114 x 178 m at 4 units per metre, 142.23 m per model unit)
  warehouse:  { halfX: 76, halfZ: 124 },   // Map 79 (Void): the container cluster and its copy turned 180°, set end to end (38 x 62 m at 4 units per metre, 1 m per model unit; the plain beyond the red edge)
  backrooms:  { halfX: 109.6, halfZ: 114.4, ceil: 15.2 },   // Original Backrooms, the whole hall (55 x 57 m at 4 units per metre, 2 m per model unit)
  backrooms_anomaly:{ halfX: 109.6, halfZ: 114.4, ceil: 15.2 },   // Original Backrooms, the whole hall (55 x 57 m at 4 units per metre, 2 m per model unit)
};
const BOUNDARY_WALL_THICKNESS = 2;
const BOUNDARY_WALL_HEIGHT = 16;

function makeBoundaryObstacles(mapKey) {
  const { halfX, halfZ } = MAP_BOUNDARY[mapKey] ?? { halfX: 138, halfZ: 138 };
  const T = BOUNDARY_WALL_THICKNESS;
  const H2 = BOUNDARY_WALL_HEIGHT * 2;
  // The slabs start AT the play extent and reach outward (alignment check
  // 2026-10-09): they used to straddle it, so online a 2 u strip inside every
  // map edge was solid that the offline arena (whose own perimeter walls sit
  // at HALF..HALF+2, outside the field, addBoundaryIndicator) leaves open —
  // the bots planned and hid differently along the edges in the two modes.
  return [
    { minX: halfX,          maxX: halfX + 2 * T,   minZ: -halfZ - 2 * T, maxZ:  halfZ + 2 * T, minY: 0, maxY: H2, topBuffer: H2 },
    { minX: -halfX - 2 * T, maxX: -halfX,          minZ: -halfZ - 2 * T, maxZ:  halfZ + 2 * T, minY: 0, maxY: H2, topBuffer: H2 },
    { minX: -halfX,         maxX:  halfX,          minZ:  halfZ,         maxZ:  halfZ + 2 * T, minY: 0, maxY: H2, topBuffer: H2 },
    { minX: -halfX,         maxX:  halfX,          minZ: -halfZ - 2 * T, maxZ: -halfZ,         minY: 0, maxY: H2, topBuffer: H2 }
  ];
}

function buildPlainField() {
  return {
    mapKey: 'arena1',
    obstacles: makeBoundaryObstacles('arena1'),
    surfaces: [],
    spawns: {
      p1: { x: -24, y: GROUND_BASE_Y, z: 0 },
      p2: { x: 24, y: GROUND_BASE_Y, z: 0 }
    }
  };
}

